this.watcher = watch(this.repoRoot, { recursive: true }, (_event, filename) => {
      const rel = toRepoRelative(this.repoRoot, filename);
      if (!rel || !isWatchable(rel)) return;
      this.scheduleRefresh();
    });

this.debounceTimer = setTimeout(() => {
      this.debounceTimer = undefined;
      void this.refresh('watcher');
    }, ms);

diagnostics.push({
            code: 'mule:dynamic-reference',
            severity: 'warning',
            message:
              'Dynamic p() argument — property key not statically determinable; no key recorded.',
          });

const push = (kind: TokKind, value: string): void => {
    tokens.push({ kind, value, line });
  };

edges.push({
        id: edgeId(sym.id, on.id, REL),
        src: sym.id,
        dst: on.id,
        rel: REL,
        method: 'static',
        provenance: 'EXTRACTED',
        confidence: 1,
        evidence: { by: 'git-blame', commit: owner.commit, head },
      });

return {
    id,
    kind: 'owner',
    hash: contentHash(id),
    name,
    ...(email ? { email } : {}),
  };
